package com.jetbrains.mpsext.mcptools.runtime;

/*Generated by MPS */

import jetbrains.mps.project.MPSProject;
import java.util.concurrent.atomic.AtomicReference;
import com.intellij.openapi.application.Application;
import com.intellij.openapi.application.ApplicationManager;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.CompletableFuture;
import com.intellij.openapi.application.ModalityState;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.ExecutionException;

/**
 * 
 * Runs a tool body with the model access it declares and turns {@link com.jetbrains.mpsext.mcptools.runtime.ToolFailure}  into an error outcome. Other
 * exceptions are passed on to the caller.
 */
public final class ToolRunner {
  public static final long COMMAND_TIMEOUT_SECONDS = 30;
  private static final int PENDING = 0;
  private static final int STARTED = 1;
  private static final int ABANDONED = 2;

  private ToolRunner() {
  }

  /**
   * 
   * Checks the arguments, then runs the body. The arguments are checked before any model access is taken, so a call
   * with bad arguments neither waits for a lock nor runs any part of the body.
   */
  public static ToolOutcome run(SyncMcpTool tool, MPSProject project, ToolArgs args) {
    try {
      args.validate(ToolSchemas.parameterTypes(tool), tool.requiredParameters());
      return ToolOutcome.success(invoke(tool, new ToolCallContext(project, args)));
    } catch (ToolFailure failure) {
      return ToolOutcome.failure(failure.getMessage());
    }
  }

  private static String invoke(final SyncMcpTool tool, final ToolCallContext context) {
    AccessMode access = tool.access();
    if (access == AccessMode.READ) {
      final AtomicReference<String> result = new AtomicReference<String>();
      context.project().getRepository().getModelAccess().runReadAction(() -> result.set(tool.call(context)));
      return result.get();
    }
    if (access == AccessMode.COMMAND) {
      return inCommand(tool, context);
    }
    return tool.call(context);
  }

  private static String inCommand(final SyncMcpTool tool, final ToolCallContext context) {
    final AtomicReference<String> result = new AtomicReference<String>();
    final AtomicReference<Throwable> error = new AtomicReference<Throwable>();
    final Runnable command = () -> context.project().getRepository().getModelAccess().executeCommand(() -> {
      try {
        result.set(tool.call(context));
      } catch (Throwable t) {
        error.set(t);
      }
    });
    Application application = ApplicationManager.getApplication();
    if (application.isDispatchThread()) {
      command.run();
    } else {
      runOnUiThread(application, command);
    }
    Throwable t = error.get();
    if (t instanceof RuntimeException) {
      throw (RuntimeException) t;
    }
    if (t instanceof Error) {
      throw (Error) t;
    }
    if (t != null) {
      throw new RuntimeException(t);
    }
    return result.get();
  }

  private static void runOnUiThread(Application application, final Runnable command) {
    final AtomicInteger state = new AtomicInteger(PENDING);
    final CompletableFuture<Void> done = new CompletableFuture<Void>();
    // MPS runs commands on the UI thread. With nonModal(), the command starts only when no modal dialog is open, so it
    // never changes the model under an open dialog.
    application.invokeLater(() -> {
      if (state.compareAndSet(PENDING, STARTED)) {
        try {
          command.run();
          done.complete(null);
        } catch (Throwable t) {
          done.completeExceptionally(t);
        }
      } else {
        done.complete(null);
      }
    }, ModalityState.nonModal());
    try {
      // Waits for the result of the command, because the tool returns it. The wait ends after COMMAND_TIMEOUT_SECONDS
      // or on an interrupt, so that a modal dialog or a long command does not block the MCP call without limit. A
      // command that has not started yet is dropped. A command that has started cannot be stopped and keeps running.
      done.get(COMMAND_TIMEOUT_SECONDS, TimeUnit.SECONDS);
    } catch (TimeoutException e) {
      if (state.compareAndSet(PENDING, ABANDONED)) {
        throw new ToolFailure("The command did not start within " + COMMAND_TIMEOUT_SECONDS + " seconds because the UI thread is busy. Close any modal dialog in the IDE and retry.");
      }
      throw new ToolFailure("The command did not finish within " + COMMAND_TIMEOUT_SECONDS + " seconds. It keeps running on the UI thread, and its result is lost.");
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      if (state.compareAndSet(PENDING, ABANDONED)) {
        throw new ToolFailure("Interrupted while waiting for the UI thread. The command did not start.");
      }
      throw new ToolFailure("Interrupted while the command runs. It keeps running on the UI thread, and its result is lost.");
    } catch (ExecutionException e) {
      Throwable cause = e.getCause();
      if (cause instanceof RuntimeException) {
        throw (RuntimeException) cause;
      }
      if (cause instanceof Error) {
        throw (Error) cause;
      }
      throw new RuntimeException(cause);
    }
  }
}
